(()=>{const keys=['utm_source','utm_medium','utm_campaign','utm_content','utm_term','utm_id','fbclid','gclid','wbraid','gbraid'];const q=new URLSearchParams(location.search);let current={};try{const old=JSON.parse(sessionStorage.getItem('meg_attribution')||'null');if(old&&Date.now()-old.at<1800000)current=old.data||{};}catch{}if(keys.some(k=>q.has(k))){current={};keys.forEach(k=>{const v=q.get(k);if(v)current[k]=v.slice(0,500)});current.landing_path=['/','/finanzas','/metodo','/metodomeg'].includes(q.get('landing_path'))?q.get('landing_path'):location.pathname;try{sessionStorage.setItem('meg_attribution',JSON.stringify({at:Date.now(),data:current}))}catch{}}document.querySelectorAll('a[href]').forEach(a=>{const u=new URL(a.href,location.href);if(u.origin!==location.origin)return;Object.entries(current).forEach(([k,v])=>u.searchParams.set(k,v));a.href=u.href});document.querySelectorAll('form').forEach(f=>{Object.entries(current).forEach(([k,v])=>{let i=f.querySelector('input[name="'+k+'"]');if(!i){i=document.createElement('input');i.type='hidden';i.name=k;f.appendChild(i)}i.value=v})});})();